// benchResourceMetrics builds a steady-state workload with attribute sets
// reused across exports.
func benchResourceMetrics(series int) *metricdata.ResourceMetrics {
	now := time.Now()
	dps := make([]metricdata.DataPoint[float64], 0, series)
	for i := range series {
		attrs := attribute.NewSet(
			attribute.String("version", "1.183.0"),
			attribute.String("env", "example-shared-prod"),
			attribute.String("projectname", "example/query-service"),
			attribute.String("host", "i-0123456789abcdef0"),
			attribute.String("configname", "production"),
			attribute.String("metric.type", "gauge"),
			attribute.Int("series", i),
		)
		dps = append(dps, metricdata.DataPoint[float64]{
			Attributes: attrs,
			StartTime:  now,
			Time:       now,
			Value:      float64(i),
		})
	}

	return &metricdata.ResourceMetrics{
		ScopeMetrics: []metricdata.ScopeMetrics{
			{
				Metrics: []metricdata.Metrics{
					{
						Name: "query_service.query.result_count.max",
						Data: metricdata.Gauge[float64]{DataPoints: dps},
					},
				},
			},
		},
	}
}

func BenchmarkResourceMetricsSteadyState(b *testing.B) {
	const series = 1000
	rm := benchResourceMetrics(series)
	// Cache sizes from disabled, through undersized, to holding every attribute set.
	for _, size := range []int{0, 100, 500, 2 * series} {
		b.Run(fmt.Sprintf("cache=%d", size), func(b *testing.B) {
			enableAttrCache(b, size)
			advance := fakeAttrCacheClock(b)
			b.ReportAllocs()
			for b.Loop() {
				advance(time.Minute)
				_, _ = ResourceMetrics(rm)
			}
		})
	}
}
